- bash (intenção: Verifying final size, citation form and resolution | comando: cd /home/one/projects/one/ai-guides/protocols/telegram_bots_guide && wc -c 25-errors-and-retries-deep.md && echo "--- .md.md occurrences:" && grep -c '\.md\.md' 25-errors-and-retries-deep.md || true && echo "--- Sources entries:" && awk '/^## Sources/{f=1;next} f&&/^- /{n++} END{print n}' 25-errors-and-retries-deep.md && echo "--- citation check:" && python3 - <<'PY'
import re, os
s=open('25-errors-and-retries-deep.md').read()
PAGES='/tmp/telegram-research/pages'; REPOS='/tmp/telegram-research/repos'
def resolve(ref):
    if '/api/methods/' in ref or '/api/types/' in ref:
        return os.path.join(PAGES,'api',ref.rsplit('/',1)[-1])
    if ref.startswith('bots/') or ref.startswith('bots_'):
        return os.path.join(PAGES, ref.replace('/','_')+'.md')
    return os.path.join(REPOS,ref)
bad=[]; total=0
for m in re.finditer(r'`([A-Za-z0-9_./-]+\.(?:md|py|ts|rs)):([0-9,\-]+)`', s):
    ref,spec=m.group(1),m.group(2); f=resolve(ref)
    if not os.path.isfile(f): bad.append((ref,spec,'missing file')); continue
    lines=open(f,errors='replace').read().splitlines()
    nums=[]
    for part in spec.split(','):
        if '-' in part:
            a,b=part.split('-'); nums.extend(range(int(a),int(b)+1))
        else: nums.append(int(part))
    for n in nums:
        total+=1
        if n>len(lines) or n<1: bad.append((ref,n,'out of range'))
print('line citations checked:',total,'problems:',bad)
PY)
